// Trino client (inline, same pattern as smart-city.json/analytics.json).
function httpsFetch(urlStr, opts = {}) { return new Promise((resolve, reject) => { let parsed; try { parsed = new urlmod.URL(urlStr); } catch (e) { return reject(new Error('bad URL')); } const lib = parsed.protocol === 'https:' ? https : http; const headers = Object.assign({}, opts.headers || {}); if (opts.body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(opts.body); const req = lib.request({ method: opts.method || 'GET', hostname: parsed.hostname, port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80), path: parsed.pathname + (parsed.search || ''), headers, timeout: opts.timeoutMs || 8000, rejectUnauthorized: opts.rejectUnauthorized !== false }, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, json: () => { try { return Promise.resolve(JSON.parse(d)); } catch (e) { return Promise.reject(e); } } })); }); req.on('error', reject); req.on('timeout', () => req.destroy(new Error('timeout'))); if (opts.body) req.write(opts.body); req.end(); }); }
const formEncode = (o) => Object.entries(o).filter(([,v]) => v !== undefined && v !== null && v !== '').map(([k,v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
async function runSql(sql) { const tres = await httpsFetch(env.get('AI_INSIGHT_TRINO__OIDC_TOKEN_URL'), { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: formEncode({ grant_type: 'password', client_id: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_ID'), client_secret: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_SECRET'), username: env.get('AI_INSIGHT_TRINO__OIDC_USERNAME'), password: env.get('AI_INSIGHT_TRINO__OIDC_PASSWORD'), scope: env.get('AI_INSIGHT_TRINO__OIDC_SCOPE') || 'openid' }), rejectUnauthorized: false }); if (!tres.ok) throw new Error('token grant failed: ' + tres.status); const token = (await tres.json()).access_token; const base = `${env.get('AI_INSIGHT_TRINO__HTTP_SCHEME') || 'https'}://${env.get('AI_INSIGHT_TRINO__HOST')}:${env.get('AI_INSIGHT_TRINO__PORT') || 8443}`; const headers = { 'Authorization': 'Bearer ' + token, 'X-Trino-User': env.get('AI_INSIGHT_TRINO__USER') || 'trino', 'X-Trino-Catalog': env.get('AI_INSIGHT_TRINO__CATALOG') || 'fap-iotai-stackable', 'Content-Type': 'text/plain' }; let res = await httpsFetch(`${base}/v1/statement`, { method: 'POST', headers, body: sql, rejectUnauthorized: false }); if (!res.ok) throw new Error('POST /v1/statement failed: ' + res.status); let body = await res.json(); let columns = body.columns || null; const rows = body.data ? [...body.data] : []; while (body.nextUri) { res = await httpsFetch(body.nextUri, { headers, rejectUnauthorized: false }); if (!res.ok) throw new Error('nextUri failed: ' + res.status); body = await res.json(); if (body.columns) columns = body.columns; if (body.data) rows.push(...body.data); } return { columns, rows }; }

// Descriptive overlay — curated metadata for tables we know about. Tables
// present in gold but absent from this map appear in the catalogue with
// description: null and domain: 'unclassified'.
const OVERLAY = {
    'net_grid_hourly':           { domain: 'energy', semanticScope: 'energy.net_grid.hourly.v1',     description: 'Net grid kW + cost rolled up hourly across the metering fleet.' },
    'energy_balance_hourly':     { domain: 'energy', semanticScope: 'energy.balance.hourly.v1',      description: 'Hourly consumption / generation / balance per site.' },
    'energy_cost_daily':         { domain: 'energy', semanticScope: 'energy.cost.daily.v1',          description: 'Daily energy cost decomposition (peak / off-peak).' },
    'pv_performance_hourly':     { domain: 'energy', semanticScope: 'energy.pv.performance.hourly.v1', description: 'Hourly PV power, irradiance and panel performance metrics.' },
    'pv_self_consumption_daily': { domain: 'energy', semanticScope: 'energy.pv.self_consumption.daily.v1', description: 'Daily PV self-consumption, autarky, export/import balance.' },
    'streetlight_zone_hourly':   { domain: 'city',   semanticScope: 'city.lighting.zone.hourly.v1',  description: 'Streetlight dimming + power, hourly per zone.' },
    'traffic_pattern_hourly':    { domain: 'city',   semanticScope: 'city.traffic.zone.hourly.v1',   description: 'Traffic index, hourly per zone.' },
    'event_impact_daily':        { domain: 'city',   semanticScope: 'city.events.zone.daily.v1',     description: 'Active city event counts and severities, daily per zone.' },
    'weather_hourly':            { domain: 'city',   semanticScope: 'city.weather.hourly.v1',        description: 'Hourly weather aggregates (temperature, irradiance, cloud cover).' },
    'city_dashboard_summary':    { domain: 'city',   semanticScope: 'city.dashboard.summary.v1',     description: 'Pre-aggregated summary view for the city dashboard.' },
    'device_utilization_daily':  { domain: 'energy', semanticScope: 'energy.devices.utilization.daily.v1', description: 'Daily device utilisation rollup.' },
    'anomaly_candidates':        { domain: 'energy', semanticScope: 'energy.anomalies.v1',           description: 'Statistical anomaly candidates flagged from hourly aggregates.' },
    'ai_insight_outputs':        { domain: 'energy', semanticScope: 'platform.ai_insight.outputs.v1',description: 'Persisted AI Insight Service outputs (energy summary / anomaly / city status reports).' }
};

function toProduct(tableName, last_updated) {
    const meta = OVERLAY[tableName] || { domain: 'unclassified', semanticScope: null, description: null };
    return {
        id: 'dp-' + tableName,
        table_name: tableName,
        name: tableName.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
        domain: meta.domain,
        semanticScope: meta.semanticScope,
        description: meta.description,
        version: 'gold',
        apiStatus: 'available',
        lastUpdated: last_updated || new Date().toISOString(),
        sourceTable: '"gold"."' + tableName + '"'
    };
}

const action = msg._req && msg._req.action;
const payload = (msg._req && msg._req.payload) || {};

try {
    if (action === 'data-products.list' || action === 'data-products.energy.list' || action === 'data-products.city.list') {
        // Fast path: derive product list from the curated OVERLAY. Trino information_schema queries against the iceberg catalog are unreliable (>60s, frequent OOMKills per project memory). The OVERLAY tables are validated to exist via per-table queries elsewhere (smart-city / analytics flows). Detail endpoint still queries Trino per-table for schema + sample.
        let products = Object.keys(OVERLAY).sort().map(t => toProduct(t));
        if (action === 'data-products.energy.list') products = products.filter(p => p.domain === 'energy');
        if (action === 'data-products.city.list')   products = products.filter(p => p.domain === 'city');
        msg._result = { ok: true, data: { products, count: products.length, metadata: { source: 'curated overlay (OVERLAY constant)', generated_at: new Date().toISOString() } } };
        return msg;
    }
    if (action === 'data-products.detail') {
        const id = String(payload.id || '');
        if (!id) { msg._result = { ok: false, errors: { fields: { id: 'required' } } }; return msg; }
        const tableName = id.replace(/^dp-/, '');
        const safe = tableName.replace(/[^A-Za-z0-9_]/g, '');
        if (!safe || safe !== tableName) { msg._result = { ok: false, errors: { fields: { id: 'invalid id' } } }; return msg; }
        const checkSql = `SELECT table_name FROM information_schema.tables WHERE table_schema = 'gold' AND table_name = '${tableName}'`;
        const exists = await runSql(checkSql);
        if (!exists.rows.length) { msg._result = { ok: false, errors: { action: 'product not found in gold schema' } }; return msg; }
        const colsSql = `SELECT column_name, data_type, is_nullable, ordinal_position FROM information_schema.columns WHERE table_schema = 'gold' AND table_name = '${tableName}' ORDER BY ordinal_position`;
        const colsResult = await runSql(colsSql);
        const sampleSql = `SELECT * FROM "gold"."${tableName}" LIMIT 5`;
        const sample = await runSql(sampleSql);
        const sampleColumns = (sample.columns || []).map(c => c.name);
        const sampleObjects = sample.rows.map(r => { const o = {}; for (let i = 0; i < sampleColumns.length; i++) o[sampleColumns[i]] = r[i]; return o; });
        const product = toProduct(tableName);
        product.schema = colsResult.rows.map(r => ({ column: r[0], type: r[1], nullable: r[2] === 'YES', position: r[3] }));
        product.sample = sampleObjects;
        msg._result = { ok: true, data: { product, metadata: { source: 'gold.' + tableName, sample_size: sampleObjects.length, generated_at: new Date().toISOString() } } };
        return msg;
    }
    msg._result = { ok: false, errors: { action: 'data-products: unknown action: ' + action } };
} catch (e) {
    node.warn('data-products query failed: ' + String(e.message || e));
    msg._result = { ok: false, errors: { integration: { service: 'trino', message: 'gold catalogue query failed' } } };
}
return msg;
